head.script:
scwin.gVar = {
    "cNextTabIDTarget" : "",
    "cNextTabIDInput" : "",
    "cNextTabIDButton" : "",
    "cNextTabIDSelectBox" : "",
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 기존 input2 있으면 삭제
    if (typeof input2 !== 'undefined') {
        input2.remove();
    }

    // 기존 button2 있으면 삭제
    if (typeof button2 !== 'undefined') {
        button2.remove();
    }

    // 기존 selectbox2 있으면 삭제
    if (typeof selectbox2 !== 'undefined') {
        selectbox2.remove();
    }

    // gdl_multiselect 재생성
    $c.gcm.createDataListMultiSelect();

    // 조건 설정 (target)
    let properties = {
        tabIndex: 2,
        nextTabID: scwin.gVar["cNextTabIDTarget"],
    };

    let cList = $c.gcm.createCList(properties);

    // 조건 설정 (input)
    let properties_input = {
        tabIndex: 3,
        nextTabID: scwin.gVar["cNextTabIDInput"],
    };

    let cList_input = $c.gcm.createCList(properties_input);

    // 조건 설정 (button)
    let properties_button = {
        tabIndex: 4,
        nextTabID: scwin.gVar["cNextTabIDButton"],
    };

    let cList_button = $c.gcm.createCList(properties_button);

    // 조건 설정 (selectbox)
    let properties_selectbox = {
        tabIndex: 5,
        nextTabID: scwin.gVar["cNextTabIDSelectBox"],
    };

    let cList_selectbox = $c.gcm.createCList(properties_selectbox);

    let grp_comp = $c.gcm.getTestGroup();

    let strNameSpace = $c.gcm.getNameSpace();
    let strStartComp = '';

    strStartComp += '<xf:input ' + strNameSpace + ' tabIndex="1" initValue="start" style="width:144px; height:21px;"></xf:input>';

    scwin.startcomp = await $p.dynamicCreate(
        "startcomp",
        "input",
        strStartComp,
        grp_comp
    );

    $c.gcm.createBasicInput(cList_input, 'ev:onfocus="scwin.input2_onfocus"', "input2");
    $c.gcm.createBasicButton(cList_button, 'ev:onfocus="scwin.button2_onfocus"', "button2");
    $c.gcm.createBasicSelectBox(cList_selectbox, 'ev:onfocus="scwin.selectbox2_onfocus"', "selectbox2");
    $c.gcm.createBasicMultiSelect(cList, 'ev:onfocus="scwin.target1_onfocus"')

    input2.setValue("input");
    scwin.changeDisplay();
}



scwin.changeDisplay = function() {
    // multiselect 부모 컨테이너가 flex/inline-block 흐름이라 block 자식이어도 같은 줄에 표시됨
    // width:100% + flex-basis:100% 로 줄 전체 차지하여 강제 줄바꿈 효과
    setTimeout(function() {
        var rootEl = document.getElementById('mf_target1') || document.getElementById('target1');
        if (rootEl) {
            rootEl.style.setProperty('display', 'block', 'important');            
            rootEl.style.setProperty('flex-basis', '100%', 'important');
        }
    }, 100);
}
